# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PEYGAMBERİMİZİN (SAV) SOYU, AİLESİ VE KUTLU DOĞUMU (571)</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">SOYU VE AİLE BÜYÜKLERİ</text>\n  <text x="40" y="92" font-size="11.5" fill="#1e3a8a">• Soyu: Hz. İbrahim\'in oğlu Hz. İsmail\'e (Adnânîler)</text>\n  <text x="40" y="114" font-size="11.5" fill="#1e3a8a">• Kabilesi: Kureyş  |  Sülalesi (Boyu): Hâşimoğulları</text>\n  <text x="40" y="136" font-size="11.5" fill="#1e3a8a">• Dedesi: Abdülmuttalip (Şeybe) — Kâbe\'nin</text>\n  <text x="48" y="152" font-size="11" fill="#3b82f6">bakımı, Zemzem kuyusunu yeniden açması, sikâye ve rifâde.</text>\n  <text x="40" y="176" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Babası: Abdullah (Doğumdan önce Şam dönüşü</text>\n  <text x="48" y="192" font-size="11" fill="#1e3a8a">Yesrib/Medine\'de vefat etti → Peygamberimiz yetim doğdu).</text>\n  <text x="40" y="216" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Annesi: Hz. Âmine (Zühreoğulları kolundan Vehb\'in kızı).</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">DOĞUMU VE İSİM VERİLMESİ</text>\n  <rect x="372" y="80" width="286" height="58" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="515" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Fil Yılı: 20 Nisan 571 (12 Rebîülevvel, Pazartesi)</text>\n  <text x="515" y="120" text-anchor="middle" font-size="11" fill="#78350f">Fil Vakası\'ndan (Ebrehe\'nin ordusunun helakından) ~50-55 gün sonra.</text>\n  <text x="372" y="158" font-size="11.5" fill="#78350f">• Dedesi Abdülmuttalip, torununu Kâbe\'ye götürerek</text>\n  <text x="380" y="174" font-size="11.5" font-weight="bold" fill="#92400e">Allah\'a şükretmiş ve \'göklerde ve yerde övülen\'</text>\n  <text x="380" y="190" font-size="11.5" font-weight="bold" fill="#92400e">anlamına gelen \'MUHAMMED\' (ve Ahmed) adını vermiştir.</text>\n  <text x="372" y="216" font-size="11" fill="#92400e">• İlk emzirenler: Annesi Hz. Âmine ve Süveybe Hatun.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÜTANNE HZ. HALİME\'NİN YANI VE ANNESİ HZ. ÂMİNE\'NİN VEFATI</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">SA\'DOĞULLARI YURDU VE HZ. HALİME (0-4 YAŞ)</text>\n  <text x="40" y="90" font-size="11.5" font-weight="bold" fill="#14532d">• Sütanneye Verilme Nedenleri:</text>\n  <text x="48" y="108" font-size="11" fill="#166534">1) Mekke\'nin sıcak/salgın hastalıklı havasından korumak</text>\n  <text x="48" y="124" font-size="11" fill="#166534">ve çölde (bâdiyede) sağlıklı büyümesini sağlamak.</text>\n  <text x="48" y="140" font-size="11" fill="#166534">2) Fasih (duru ve kusursuz) Arapçayı öğrenmesini sağlamak.</text>\n  <text x="40" y="164" font-size="11.5" font-weight="bold" fill="#14532d">• Sütannesi ve Sütkardeşleri:</text>\n  <text x="48" y="182" font-size="11" fill="#166534">Hevâzin kabilesinin Sa\'doğulları kolundan Hz. Halime</text>\n  <text x="48" y="198" font-size="11" fill="#166534">(Eşi: Hâris; Sütkardeşleri: Abdullah, Üneyse ve Şeymâ).</text>\n  <text x="48" y="218" font-size="10.5" font-weight="bold" fill="#15803d">Hz. Halime\'nin evine bolluk ve bereket gelmiştir.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">EBVÂ\'DA HZ. ÂMİNE\'NİN VEFATI (6 YAŞ)</text>\n  <text x="370" y="92" font-size="11.5" fill="#581c87">• 4 yaşında Mekke\'ye annesi Hz. Âmine\'nin yanına döndü.</text>\n  <text x="370" y="116" font-size="11.5" fill="#581c87">• 6 yaşına geldiğinde annesi Hz. Âmine ve sadık dadısı</text>\n  <text x="378" y="134" font-size="11.5" font-weight="bold" fill="#7e22ce">Ümmü Eymen (Bereke) ile birlikte babası Abdullah\'ın</text>\n  <text x="378" y="150" font-size="11.5" fill="#581c87">kabrinin bulunduğu Yesrib\'e (Medine\'ye) gitti.</text>\n  <rect x="370" y="164" width="290" height="64" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="515" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Ebvâ Köyü (Mekke Dönüşü):</text>\n  <text x="515" y="202" text-anchor="middle" font-size="11" fill="#581c87">Hz. Âmine dönüş yolunda Ebvâ köyünde hastalanarak</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" fill="#581c87">vefat etti; Ümmü Eymen onu Mekke\'ye dedesine ulaştırdı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DEDESİ ABDÜLMUTTALİP (6-8 YAŞ) VE AMCASI EBÛ TALİP\'İN HİMAYESİ (8+ YAŞ)</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">ABDÜLMUTTALİP\'İN HİMAYESİ (6 - 8 YAŞ)</text>\n  <text x="40" y="92" font-size="11.5" fill="#7c2d12">• Hem yetim hem öksüz kalan Peygamberimizi dedesi</text>\n  <text x="48" y="110" font-size="11.5" font-weight="bold" fill="#c2410c">Abdülmuttalip büyük bir şefkat ve merhametle bağrına bastı.</text>\n  <text x="40" y="136" font-size="11.5" fill="#7c2d12">• Kâbe gölgesinde kendisi için serilen özel mindere</text>\n  <text x="48" y="154" font-size="11.5" fill="#7c2d12">yalnızca torunu Hz. Muhammed\'in oturmasına izin verirdi.</text>\n  <text x="40" y="180" font-size="11.5" fill="#7c2d12">• Peygamberimiz 8 yaşındayken dedesi Abdülmuttalip</text>\n  <text x="48" y="198" font-size="11.5" font-weight="bold" fill="#9a3412">vefat etti; ölmeden önce onu öz amcası Ebû Talip\'e</text>\n  <text x="48" y="216" font-size="11.5" fill="#7c2d12">emanet etti (Abdullah ile Ebû Talip anne-baba bir kardeştir).</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">EBÛ TALİP VE Fâtıma BİNTİ ESED (8 YAŞ SONRASI)</text>\n  <text x="370" y="92" font-size="11.5" fill="#164e63">• Amcası Ebû Talip ve yengesi Fâtıma binti Esed,</text>\n  <text x="378" y="110" font-size="11.5" font-weight="bold" fill="#0e7490">Peygamberimizi kendi çocuklarından bile üstün tuttular.</text>\n  <text x="370" y="136" font-size="11.5" fill="#164e63">• Peygamberimiz amcasına yük olmamak ve ailesine</text>\n  <text x="378" y="152" font-size="11.5" fill="#164e63">katkıda bulunmak için Mekke\'de çobanlık yaptı.</text>\n  <text x="370" y="176" font-size="11.5" fill="#164e63">• 9-12 yaşlarında amcası Ebû Talip ile Şam ticaret</text>\n  <text x="378" y="192" font-size="11.5" font-weight="bold" fill="#0e7490">kervanına katıldı (Busrâ kasabası / Rahip Bahîrâ olayı).</text>\n  <text x="370" y="218" font-size="11" fill="#155e75">• Cahiliye kötülüklerinden korunarak iffetli bir gençlik geçirdi.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
